function parseRow(r) {
  const [id, name, nameEn, alt, category, equip, primary, secondary, pattern, flags] = r;
  const f = flags.split(' ');
  const has = t => f.includes(t);
  const load = has('w') ? 'weight' : has('bw') ? 'bodyweight' : has('band') ? 'band' : 'none';
  const tags = ['iso', 'ecc', 'plyo'].filter(has).map(t => ({ iso: 'isometric', ecc: 'eccentric', plyo: 'plyometric' }[t]));
  return {
    id, name, nameEn, alt: alt ? alt.split('|') : [], category,
    equipment: equip ? equip.split(',') : [], primary, secondary: secondary ? secondary.split(',').filter(Boolean) : [],
    pattern, mechanic: has('C') ? 'compound' : 'isolation', laterality: has('U') ? 'unilateral' : 'bilateral',
    load, measure: has('t') ? 'time' : 'reps', difficulty: Number(f.find(x => /^[123]$/.test(x)) || 1), tags,
    easier: [], harder: [], tip: TIPS[id] || '', custom: false,
  };
}

export function buildLibrary() {
  const list = ROWS.map(parseRow);
  const byId = Object.fromEntries(list.map(e => [e.id, e]));
  for (const chain of CHAINS) {
    for (let i = 0; i < chain.length; i++) {
      const e = byId[chain[i]];
      if (!e) continue;
      if (i > 0 && byId[chain[i - 1]] && !e.easier.includes(chain[i - 1])) e.easier.push(chain[i - 1]);
      if (i < chain.length - 1 && byId[chain[i + 1]] && !e.harder.includes(chain[i + 1])) e.harder.push(chain[i + 1]);
    }
  }
  return list;
}

export function instructionsFor(ex) {
  const p = PATTERNS[ex.pattern] || PATTERNS.conditioning;
  return { steps: ex.steps && ex.steps.length ? ex.steps : p.steps, mistakes: ex.mistakes && ex.mistakes.length ? ex.mistakes : p.mistakes, patternLabel: p.label };
}

